'use strict';
const $=id=>document.getElementById(id);const msg=text=>$('message').textContent=text;
async function api(path,options={}){const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw Error(data.error||'操作失败');return data;}
function add(parent,tag,text,className){const e=document.createElement(tag);e.textContent=text;if(className)e.className=className;parent.append(e);return e;}
function makeLink(parent,label,href){const e=add(parent,'a',label,'button secondary');e.href=href;e.target='_blank';e.rel='noopener noreferrer';return e;}
function render(data){$('identity').textContent='我的编号：'+data.code;$('login-card').hidden=true;$('dashboard').hidden=false;const host=$('programs');host.replaceChildren();const groups=new Map();for(const row of data.lessons){if(!groups.has(row.program_id))groups.set(row.program_id,[]);groups.get(row.program_id).push(row);}for(const rows of groups.values()){const first=rows[0],section=add(host,'section','', 'program');add(section,'span',first.kind==='camp'?`${first.days} 天创作营`:'半天创作课','eyebrow');add(section,'h2',first.program_title);if(first.description)add(section,'p',first.description,'muted');const grid=add(section,'div','','topic');for(const item of rows){const card=add(grid,'article','','card');add(card,'span',`第 ${item.day_no} 天 · ${item.lesson_title}`,'eyebrow');add(card,'h3',item.lesson_title);add(card,'span',item.status||'未提交','status '+(item.status==='已发布'?'published':item.status==='待审核'?'pending':''));if(item.error)add(card,'p','老师的修改建议：'+item.error,'feedback');const tools=add(card,'div','','actions');if(item.starter_available){const a=add(tools,'a','下载起始包','button secondary');a.href=`/api/student/lessons/${item.lesson_id}/starter.zip`;a.download=`${item.lesson_slug}-starter.zip`;}else add(tools,'span','老师还未准备起始包','muted');const field=add(card,'div');const label=add(field,'label','上传做好的 ZIP：');const picker=add(field,'input');picker.type='file';picker.accept='.zip,application/zip';label.append(picker);const send=add(field,'button','提交这个课题的作品');send.onclick=async()=>{const file=picker.files[0];if(!file)return msg('请先选择 ZIP 文件');if(file.size>25_000_000)return msg('ZIP 不得超过 25MB');send.disabled=true;msg('正在上传并检查，请稍等…');try{await api(`/api/student/submit/${item.lesson_id}`,{method:'POST',headers:{'Content-Type':'application/zip'},body:file});await refresh();msg(`${item.lesson_title} 上传成功，等待老师审核。`);}catch(e){msg(e.message);}finally{send.disabled=false;}};if(item.url){const delivery=add(card,'div','','actions');makeLink(delivery,'打开我的作品',item.url);const qr=item.format==='money'?`https://codexai.site/api/works/${data.code}/qr.png`:`https://codexai.site/api/projects/${data.code}/${item.lesson_slug}/qr.png`;makeLink(delivery,'给家长扫码',qr);const copy=add(delivery,'button','复制家长链接','secondary');copy.onclick=async()=>{try{await navigator.clipboard.writeText(item.url);msg('作品链接已复制');}catch{msg('复制失败，请打开作品后复制浏览器地址');}};}}}if(!data.lessons.length)add(host,'p','老师还没有为你分配课程，请稍后刷新。','empty');}
async function refresh(){try{render(await api('/api/student/dashboard'));msg('课程和作品状态已更新。');}catch(e){$('dashboard').hidden=true;$('login-card').hidden=false;msg(e.message);}}
$('login').onclick=async()=>{const code=$('code').value.trim().toLowerCase(),token=$('token').value.trim();try{await api('/api/student/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,token})});$('token').value='';await refresh();}catch(e){msg(e.message);}};
$('logout').onclick=async()=>{try{await api('/api/student/logout',{method:'POST'});}catch{}$('dashboard').hidden=true;$('login-card').hidden=false;msg('已退出。');};
$('refresh').onclick=refresh;
refresh();
